import {randomUUID} from 'node:crypto';
import {
  Catch,
  HttpException,
  type ArgumentsHost,
  type ExceptionFilter,
  type NestMiddleware,
} from '@nestjs/common';
import type {NextFunction, Request, Response} from 'express';
import {ApiErrorEnvelopeSchema, type ApiErrorEnvelope, type ErrorCode} from '@me-palnadu/contracts';
import {ApiError, statusForErrorCode} from './api-error.js';
import {mapPersistenceError} from './persistence-error.js';

/**
 * Every response that carries an error uses this envelope. It is generated by the
 * contracts schema and then parsed back through it, so a malformed envelope is a
 * bug that fails in tests rather than a shape a client has to guess.
 */

export interface RequestWithId extends Request {
  id?: string;
}

/** Attaches a correlation id to every request, and echoes it back. */
export class RequestIdMiddleware implements NestMiddleware {
  use(request: RequestWithId, response: Response, next: NextFunction): void {
    const incoming = request.headers['x-request-id'];
    const id =
      typeof incoming === 'string' && incoming.length > 0 && incoming.length <= 128
        ? incoming
        : randomUUID();
    request.id = id;
    response.setHeader('x-request-id', id);
    next();
  }
}

/**
 * The status an error carries, when it is a transport-level failure rather than a
 * Nest exception.
 *
 * `express`'s JSON parser rejects an oversize body by throwing a plain object with
 * `status`/`statusCode` set and `type: 'entity.too.large'` - it is not an
 * `HttpException`, so the `instanceof` branch never sees it and it used to fall through
 * to the persistence mapper as a 500.
 *
 * The range check is deliberate: only a 4xx is treated as the caller's problem. A
 * driver error carrying a numeric field must not be reinterpreted as one, and this
 * runs before the persistence mapper only for statuses a client could have caused.
 */
const transportStatus = (error: unknown): number | null => {
  if (typeof error !== 'object' || error === null) return null;
  const candidate = error as {status?: unknown; statusCode?: unknown};
  const value = typeof candidate.status === 'number' ? candidate.status : candidate.statusCode;
  if (typeof value !== 'number' || !Number.isInteger(value)) return null;
  return value >= 400 && value <= 499 ? value : null;
};

/**
 * HTTP-level failures, mapped onto the contract's error codes.
 *
 * Without this, an unmatched route raised Nest's `NotFoundException`, which carries a
 * `statusCode` rather than a contract `code`, fell through to the persistence mapper,
 * and answered an ordinary typo'd URL with a 500. That is wrong in three ways at
 * once: the status misleads the caller, the noise trains operators to ignore 500s,
 * and it hides real server faults among them.
 *
 * Messages are replaced rather than forwarded. Nest's text embeds the requested path,
 * and echoing caller input back inside an error body is not something a JSON API
 * should do by default.
 */
const mapHttpException = (status: number): ApiError => {
  switch (status) {
    case 400:
      return ApiError.badRequest('The request could not be understood.');
    case 401:
      return ApiError.unauthenticated('The session token is not valid.');
    case 403:
      return new ApiError('FORBIDDEN', 'This account may not perform that action.');
    case 404:
      return ApiError.notFound('No route matches the requested path.');
    case 413:
      // Reached when a body exceeds the configured limit. Previously this fell to the
      // default branch and answered 500, which told the caller - and any alert that
      // watches 5xx - that the server had failed rather than that the request was too
      // big to accept.
      return ApiError.payloadTooLarge('The request body is larger than this API accepts.');
    case 429:
      return new ApiError('RATE_LIMITED', 'Too many requests. Slow down and retry later.');
    default:
      return ApiError.internal();
  }
};

@Catch()
export class ApiExceptionFilter implements ExceptionFilter {
  private readonly logger = new ApiExceptionFilterLogger();

  catch(error: unknown, host: ArgumentsHost): void {
    const http = host.switchToHttp();
    const request = http.getRequest<RequestWithId>();
    const response = http.getResponse<Response>();
    const requestId = request.id ?? 'unknown';

    // `logDetail` is the server-side description. The client only ever receives the
    // contract envelope, so an unexpected error keeps its diagnostic while the
    // response stays opaque.
    const mapped =
      error instanceof ApiError
        ? {error, logDetail: `${error.name}: ${error.message}`}
        : error instanceof HttpException
          ? {
              error: mapHttpException(error.getStatus()),
              logDetail: `HttpException ${error.getStatus()}`,
            }
          : transportStatus(error) !== null
            ? {
                error: mapHttpException(transportStatus(error) as number),
                logDetail: `transport error status ${String(transportStatus(error))}`,
              }
            : mapPersistenceError(error);

    if (mapped.error.code === 'INTERNAL_ERROR') {
      // Log the safe-to-log detail once; never forward it to the client.
      this.logger.error({requestId, detail: mapped.logDetail});
    } else if (mapped.error.code === 'RATE_LIMITED') {
      this.logger.warn({requestId, detail: mapped.logDetail});
    }

    const envelope = buildEnvelope(mapped.error, requestId);
    response.status(statusForErrorCode(mapped.error.code)).json(envelope);
  }
}

export const buildEnvelope = (error: ApiError, requestId: string): ApiErrorEnvelope => {
  const candidate = {
    error: {
      code: error.code,
      message: error.message,
      requestId,
      ...(error.details === undefined ? {} : {details: error.details}),
    },
  } satisfies ApiErrorEnvelope;

  // Parsing our own output through the contract makes drift impossible to ship.
  return ApiErrorEnvelopeSchema.parse(candidate);
};

/** Minimal structured logger; swapped for pino when log shipping is configured. */
class ApiExceptionFilterLogger {
  error(context: Record<string, unknown>): void {
    console.error(JSON.stringify({level: 'error', ...context}));
  }

  warn(context: Record<string, unknown>): void {
    console.warn(JSON.stringify({level: 'warn', ...context}));
  }
}

export type {ErrorCode};
